import express from 'express';

const produk = [];
let nextId = 1;
const app = express();
app.use(express.json());
app.post('/produk', (req, res) => {
  const p = { id: nextId++, nama: req.body.nama };
  produk.push(p);
  res.status(201).json(p);
});
app.put('/produk/:id', (req, res) => {
  const id = Number(req.params.id);
  const i = produk.findIndex((p) => p.id === id);
  const data = { id, nama: req.body.nama };
  if (i === -1) produk.push(data); else produk[i] = data;
  res.json(data);
});
app.delete('/produk/:id', (req, res) => {
  const i = produk.findIndex((p) => p.id === Number(req.params.id));
  if (i !== -1) produk.splice(i, 1);
  res.sendStatus(204);
});
const server = app.listen(3000);

const kirim = (method, jalur, body) => fetch('http://localhost:3000' + jalur, { method, headers: { 'Content-Type': 'application/json' }, body: body && JSON.stringify(body) });
for (let i = 0; i < 2; i++) await kirim('POST', '/produk', { nama: 'Kopi' });
console.log('setelah 2x POST:', produk.length);
for (let i = 0; i < 2; i++) await kirim('PUT', '/produk/1', { nama: 'Kopi Susu' });
console.log('setelah 2x PUT:', produk.length, produk[0].nama);
for (let i = 0; i < 2; i++) await kirim('DELETE', '/produk/2');
console.log('setelah 2x DELETE:', produk.length);
server.close();

