import express from 'express';
const produk = [{ id: 1, nama: 'Kopi', kategori: 'minuman' }, { id: 2, nama: 'Roti', kategori: 'makanan' }];
const app = express();
app.get('/produk', (req, res) => res.json(produk));
app.get('/produk/:id', (req, res) => {
  const p = produk.find((x) => x.id === Number(req.params.id));
  if (!p) return res.status(404).json({ error: 'Produk tidak ada' });
  res.json(p);
});
app.get('/kategori/:nama/produk', (req, res) => {
  res.json(produk.filter((p) => p.kategori === req.params.nama));
});
const server = app.listen(3000);
console.log((await (await fetch('http://localhost:3000/produk')).json()).length);
console.log((await (await fetch('http://localhost:3000/produk/1')).json()).nama);
console.log((await (await fetch('http://localhost:3000/kategori/makanan/produk')).json()).map((p) => p.nama));
server.close();

