import express from 'express';
const pesanan = [{ id: 1, penggunaId: 1 }, { id: 2, penggunaId: 2 }, { id: 3, penggunaId: 2 }];
const app = express();
app.get('/pengguna/:id/pesanan', (req, res) => {
  res.json(pesanan.filter((p) => p.penggunaId === Number(req.params.id)));
});
const server = app.listen(3000);
console.log((await (await fetch('http://localhost:3000/pengguna/2/pesanan')).json()).length);
server.close();
